BEGIN READ ONLY; SET LOCAL statement_timeout = '10s'; SELECT json_build_object('captured_at',clock_timestamp(),'database_bytes',pg_database_size(current_database()),'server_version',version(),'relations',(SELECT json_agg(x) FROM (SELECT c.relname AS name,pg_total_relation_size(c.oid) AS total_bytes FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='public' AND c.relkind='r' ORDER BY c.relname) x)); COMMIT;
